after.load.ts:
export async function load(read: () => Promise<string>) {
  try { return await read(); }
  catch (error: unknown) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`load failed: ${message}`, { cause: error });
  }
}

before.result.ts:
type Result = { ok: true; value: string } | { ok: false; error: unknown };
export async function readResult(read: () => Promise<string>): Promise<Result> {
  return { ok: true, value: await read() };
}

after.result.ts:
type Result = { ok: true; value: string } | { ok: false; error: unknown };
export async function readResult(read: () => Promise<string>): Promise<Result> {
  try { return { ok: true, value: await read() }; }
  catch (error) { return { ok: false, error }; }
}

before.locked.ts:
export async function locked(mutex: Mutex, work: () => Promise<void>) {
  await mutex.acquire();
  await work();
  mutex.release();
}

after.locked.ts:
export async function locked(mutex: Mutex, work: () => Promise<void>) {
  await mutex.acquire();
  try { await work(); } finally { mutex.release(); }
}

after.name.ts:
export function name(value: string | null) {
  if (value === null) return '';
  return value.trim();
}

